//! Guest SDK for PeltyCMS WASM addons.
//!
//! An addon crate depends on this SDK and calls one macro, e.g.
//! `pelty_addon_sdk::gateway_addon!(my::descriptor, my::factory);`. The SDK
//! implements the WIT exports (`describe`, `call`, `on-event`) and routes
//! HTTP from the shared module code to the host's `http-fetch` import.
//! Handwritten code here has no `unsafe`; the ABI glue generated by
//! wit-bindgen does, and runs inside the host's sandbox.
/// Rust SDK crate version; independent of the manifest ABI and provider API versions.
pub const SDK_VERSION: &str = env!("CARGO_PKG_VERSION");
/// WIT package identity used by these generated bindings (not the manifest ABI).
pub const WIT_PACKAGE_VERSION: &str = "0.2.0";
/// Latest manifest ABI feature level documented by this SDK.
/// This is not the minimum host version required by every addon.
pub const ABI_VERSION: &str = "0.5.0";
/// Baseline generic addon ABI. Newer imported interfaces can require a newer host.
pub const BASE_ABI_VERSION: &str = "0.2.0";
/// Minimum manifest feature level for the optional `scheduled` export.
#[cfg(feature = "cron")]
pub const CRON_ABI_VERSION: &str = "0.5.0";

#[cfg(not(feature = "cron"))]
wit_bindgen::generate!({
    path: "../../../crates/pelty-wasm/wit/pelty.wit",
    world: "pelty-addon",
    pub_export_macro: true,
    default_bindings_module: "pelty_addon_sdk",
});
// Feature `cron` (ABI 0.5): the `pelty-addon-cron` world, which adds the
// `scheduled` export. Every SDK macro then exports `on-cron` too (routed to
// [`Addon::cron`] for integration addons); crates that implement the WIT
// exports by hand must also implement [`ScheduledGuest`].
#[cfg(feature = "cron")]
wit_bindgen::generate!({
    path: "../../../crates/pelty-wasm/wit/pelty.wit",
    world: "pelty-addon-cron",
    pub_export_macro: true,
    default_bindings_module: "pelty_addon_sdk",
});
#[cfg(feature = "cron")]
pub use exports::pelty::addon::scheduled::Guest as ScheduledGuest;

/// Implements the `scheduled` export (feature `cron`) for an SDK macro's
/// guest type; without the feature it expands to nothing.
#[cfg(feature = "cron")]
#[doc(hidden)]
#[macro_export]
macro_rules! __cron_export {
    ($guest:ty, $body:expr) => {
        impl $crate::ScheduledGuest for $guest {
            fn on_cron(job: String) -> Result<String, String> {
                let f: fn(&str) -> Result<String, String> = $body;
                f(&job)
            }
        }
    };
}
#[cfg(not(feature = "cron"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __cron_export {
    ($guest:ty, $body:expr) => {};
}

pub use exports::pelty::addon::addon::Guest;
pub use pelty::addon::host;
/// Opt-in powers (db, sql, exec, jobs); each needs an approved capability.
pub use pelty::addon::power;
/// Addon-defined events (ABI 0.3): `emit` runs the `before` phase.
pub use pelty::addon::events;
pub use serde_json;

/// Drive a future to completion. Host imports are synchronous, so module
/// futures never stay pending; a pending poll is reported as an error.
pub fn block_on<F: std::future::Future>(f: F) -> Result<F::Output, String> {
    let mut f = std::pin::pin!(f);
    let mut cx = std::task::Context::from_waker(std::task::Waker::noop());
    for _ in 0..1_000_000 {
        if let std::task::Poll::Ready(v) = f.as_mut().poll(&mut cx) {
            return Ok(v);
        }
    }
    Err("future did not complete".into())
}

/// Raw HTTP through the host.
pub fn fetch(method: &str, url: &str, headers: Vec<(String, String)>, body: String) -> Result<(u16, String), String> {
    let r = host::http_fetch(&host::HttpRequest { method: method.into(), url: url.into(), headers, body })?;
    Ok((r.status, r.body))
}

/// Result of emitting an addon event.
#[derive(Debug, Clone)]
pub struct Emitted {
    pub cancelled: bool,
    pub reason: Option<String>,
    /// Payload after every `before` listener (modifications applied).
    pub payload: serde_json::Value,
}

/// Emit `<own-id>:<name>` (declared in `capabilities.emits`). Listeners of
/// other addons may cancel or modify it; `after`/`finished` follow.
pub fn emit(name: &str, payload: &serde_json::Value) -> Result<Emitted, String> {
    let out: serde_json::Value = serde_json::from_str(&events::emit(name, &payload.to_string())?).map_err(|e| e.to_string())?;
    Ok(Emitted { cancelled: out["cancelled"].as_bool().unwrap_or(false), reason: out["reason"].as_str().map(str::to_string), payload: out["payload"].clone() })
}

/// The context of the operation being served (ABI 0.4): which hook, filter
/// or mixin called the addon, its phase and priority. `Null` outside one.
pub fn context() -> serde_json::Value {
    serde_json::from_str(&pelty::addon::context::current()).unwrap_or(serde_json::Value::Null)
}

/// Apply this addon's own filter point `<own-id>:<point>` (ABI 0.4, declared
/// in `capabilities.filter_points`): other addons subscribed to it rewrite
/// `value`. Never fails; returns `value` unchanged when nothing applies.
pub fn apply_filter(name: &str, value: &serde_json::Value, context: &serde_json::Value) -> serde_json::Value {
    serde_json::from_str(&pelty::addon::filters::apply(name, &value.to_string(), &context.to_string())).unwrap_or_else(|_| value.clone())
}

/// Replies for the `hook` op (`input = {event, phase, payload, cancelled}`).
pub mod reply {
    use serde_json::{json, Value};
    pub fn proceed() -> Value {
        json!({ "action": "continue" })
    }
    pub fn modify(payload: Value) -> Value {
        json!({ "action": "modify", "payload": payload })
    }
    pub fn cancel(reason: &str) -> Value {
        json!({ "action": "cancel", "reason": reason })
    }
    /// Only honoured for hooks with `ignore_cancelled: true`.
    pub fn uncancel() -> Value {
        json!({ "action": "uncancel" })
    }
    /// `filter` op reply: the (possibly changed) value, same JSON shape.
    pub fn filter(value: Value) -> Value {
        json!({ "value": value })
    }
    /// `http` op reply.
    pub fn http(status: u16, body: Value) -> Value {
        json!({ "status": status, "body": body })
    }
    /// `mixin` reply in the before phase: new request body (`None` keeps it)
    /// plus state handed to the after phase of an `around` mixin.
    pub fn mixin_before(body: Option<Value>, state: Value) -> Value {
        match body {
            Some(b) => json!({ "body": b, "state": state }),
            None => json!({ "state": state }),
        }
    }
    /// `mixin` reply in the after phase: the new response (same JSON shape).
    pub fn mixin_response(response: Value) -> Value {
        json!({ "response": response })
    }
    /// Core-function mixin (`fn <name>` target), before phase: the new
    /// function input (`None` keeps it) plus state for the after phase.
    pub fn fn_input(input: Option<Value>, state: Value) -> Value {
        match input {
            Some(i) => json!({ "input": i, "state": state }),
            None => json!({ "state": state }),
        }
    }
    /// Core-function mixin, after phase: the new output (same JSON shape).
    pub fn fn_output(output: Value) -> Value {
        json!({ "output": output })
    }
    /// `mixin` reply that changes nothing.
    pub fn mixin_keep() -> Value {
        json!({})
    }
}

/// Typed views of the inputs the host passes to `call(op, input)`. Each keeps
/// the full input in `raw`, so new host fields stay reachable.
pub mod op {
    use serde_json::Value;
    fn s(v: &Value, k: &str) -> String {
        v[k].as_str().unwrap_or_default().to_string()
    }

    /// `hook`: a hook subscription fired (`capabilities.hooks`).
    #[derive(Debug, Clone)]
    pub struct Hook {
        pub event: String,
        /// `before`, `during`, `after` or `finished`.
        pub phase: String,
        pub payload: Value,
        /// Set when an earlier `before` hook cancelled (see `ignore_cancelled`).
        pub cancelled: bool,
        pub raw: Value,
    }
    impl Hook {
        pub fn parse(v: Value) -> Self {
            Hook { event: s(&v, "event"), phase: s(&v, "phase"), payload: v["payload"].clone(), cancelled: v["cancelled"].as_bool().unwrap_or(false), raw: v }
        }
        /// String field of the payload.
        pub fn str(&self, key: &str) -> Option<&str> {
            self.payload[key].as_str()
        }
    }

    /// `filter`: a value filter (`capabilities.filters`).
    #[derive(Debug, Clone)]
    pub struct Filter {
        pub name: String,
        pub value: Value,
        pub context: Value,
        pub raw: Value,
    }
    impl Filter {
        pub fn parse(v: Value) -> Self {
            Filter { name: s(&v, "filter"), value: v["value"].clone(), context: v["context"].clone(), raw: v }
        }
    }

    /// `http`: a request to the addon's own routes (`/api/v1/addons/<id>/...`).
    #[derive(Debug, Clone)]
    pub struct Http {
        pub method: String,
        pub path: String,
        pub params: Value,
        pub query: Value,
        pub body: Value,
        /// `{id, roles, admin}` of the signed-in caller, if any.
        pub user: Option<Value>,
        /// The request came from the addon's own UI frame.
        pub frame: bool,
        pub raw: Value,
    }
    impl Http {
        pub fn parse(v: Value) -> Self {
            Http {
                method: s(&v, "method"),
                path: s(&v, "path"),
                params: v["params"].clone(),
                query: v["query"].clone(),
                body: v["body"].clone(),
                user: Some(v["user"].clone()).filter(|u| !u.is_null()),
                frame: v["frame"].as_bool().unwrap_or(false),
                raw: v,
            }
        }
        pub fn is_admin(&self) -> bool {
            self.user.as_ref().is_some_and(|u| u["admin"] == true)
        }
    }

    /// `mixin`: a wrapped core route (`capabilities.mixins`).
    #[derive(Debug, Clone)]
    pub struct Mixin {
        pub target: String,
        /// `before`, `after`, `around` or `return`.
        pub at: String,
        /// `before` (request rewrite) or `after` (response rewrite).
        pub phase: String,
        pub request: Value,
        /// After phase only.
        pub response: Value,
        pub status: Option<u16>,
        /// What the before phase returned as `state` (`around`).
        pub state: Value,
        /// Core-function mixins (`fn <name>` target): the function name,
        /// its read-only context, its input and (after phase) its output.
        pub function: Option<String>,
        pub context: Value,
        pub input: Value,
        pub output: Value,
        pub raw: Value,
    }
    impl Mixin {
        /// True for a core-function mixin.
        pub fn is_function(&self) -> bool {
            self.function.is_some()
        }
        pub fn parse(v: Value) -> Self {
            Mixin {
                target: s(&v, "target"),
                at: s(&v, "at"),
                phase: s(&v, "phase"),
                request: v["request"].clone(),
                response: v["response"].clone(),
                status: v["status"].as_u64().and_then(|x| u16::try_from(x).ok()),
                state: v["state"].clone(),
                function: v["function"].as_str().map(str::to_string),
                context: v["context"].clone(),
                input: v["input"].clone(),
                output: v["output"].clone(),
                raw: v,
            }
        }
    }
}

/// An integration addon: implement what you need, the defaults are no-ops
/// (hooks proceed, filters keep the value, unknown routes return 404).
/// Export it with [`integration_addon!`].
pub trait Addon {
    /// `describe()` descriptor (at least `id` and `name`).
    fn describe() -> serde_json::Value;
    fn hook(_h: &op::Hook) -> Result<serde_json::Value, String> {
        Ok(reply::proceed())
    }
    fn filter(f: &op::Filter) -> Result<serde_json::Value, String> {
        Ok(reply::filter(f.value.clone()))
    }
    fn http(_r: &op::Http) -> Result<serde_json::Value, String> {
        Ok(reply::http(404, serde_json::Value::Null))
    }
    fn mixin(_m: &op::Mixin) -> Result<serde_json::Value, String> {
        Ok(reply::mixin_keep())
    }
    /// Any other op (jobs, scheduled tasks, `auth.verify`, custom ops).
    fn op(name: &str, _input: serde_json::Value) -> Result<serde_json::Value, String> {
        Err(format!("unknown op {name}"))
    }
    /// Subscribed events (`capabilities.events`).
    fn event(_name: &str, _payload: serde_json::Value) -> Result<(), String> {
        Ok(())
    }
    /// A cron job from `capabilities.cron` (ABI 0.5: build with the SDK's
    /// `cron` feature and set `"abi": "0.5.0"`). The returned JSON is the
    /// run's result.
    fn cron(job: &str) -> Result<serde_json::Value, String> {
        Err(format!("unknown cron job {job}"))
    }
}

/// Route `on-cron` to an [`Addon`].
pub fn dispatch_cron<A: Addon>(job: &str) -> Result<String, String> {
    A::cron(job).map(|v| v.to_string())
}

/// Route one `call(op, input)` to an [`Addon`].
pub fn dispatch<A: Addon>(op_name: &str, input: &str) -> Result<String, String> {
    let v: serde_json::Value = if input.is_empty() { serde_json::Value::Null } else { serde_json::from_str(input).map_err(|e| e.to_string())? };
    let out = match op_name {
        "hook" => A::hook(&op::Hook::parse(v))?,
        "filter" => A::filter(&op::Filter::parse(v))?,
        "http" => A::http(&op::Http::parse(v))?,
        "mixin" => A::mixin(&op::Mixin::parse(v))?,
        other => A::op(other, v)?,
    };
    Ok(out.to_string())
}

/// Route `on-event` to an [`Addon`].
pub fn dispatch_event<A: Addon>(name: &str, payload: &str) -> Result<(), String> {
    A::event(name, serde_json::from_str(payload).unwrap_or(serde_json::Value::Null))
}

/// Export an integration addon from a type implementing [`Addon`]:
/// `pelty_addon_sdk::integration_addon!(MyAddon);`
#[macro_export]
macro_rules! integration_addon {
    ($addon:ty) => {
        struct PeltyAddonGuest;
        impl $crate::Guest for PeltyAddonGuest {
            fn describe() -> String {
                <$addon as $crate::Addon>::describe().to_string()
            }
            fn call(op: String, input: String) -> Result<String, String> {
                $crate::dispatch::<$addon>(&op, &input)
            }
            fn on_event(name: String, payload: String) -> Result<(), String> {
                $crate::dispatch_event::<$addon>(&name, &payload)
            }
        }
        $crate::__cron_export!(PeltyAddonGuest, |job| $crate::dispatch_cron::<$addon>(job));
        $crate::export!(PeltyAddonGuest with_types_in $crate);
    };
}

pub fn log_info(msg: &str) {
    host::log(host::Level::Info, msg);
}

/// Setting value as JSON.
pub fn setting(key: &str) -> Option<serde_json::Value> {
    host::setting(key).and_then(|s| serde_json::from_str(&s).ok())
}

#[cfg(feature = "gateway")]
pub mod gateway {
    use pelty_payments::{BoxFuture, GatewayDescriptor, GatewayError, GatewayFactory, HttpRequestSpec, HttpTransport};
    use serde_json::Value;
    use std::sync::Arc;

    /// [`HttpTransport`] backed by the host's `http-fetch`.
    pub struct HostTransport;
    impl HttpTransport for HostTransport {
        fn send(&self, req: HttpRequestSpec) -> BoxFuture<'_, Result<(u16, String), String>> {
            Box::pin(async move { crate::fetch(req.method, &req.url, req.headers, req.body) })
        }
    }

    pub fn describe(d: &GatewayDescriptor) -> String {
        serde_json::to_string(d).unwrap_or_else(|_| "{}".into())
    }

    pub fn call(d: &GatewayDescriptor, f: GatewayFactory, op: &str, input: &str) -> Result<String, String> {
        let input: Value = serde_json::from_str(input).map_err(|e| format!("malformed_payload:{e}"))?;
        let bo = |fut: BoxFuture<'_, Result<Value, GatewayError>>| crate::block_on(fut).map_err(GatewayError::Provider)?;
        let out = pelty_payments::wire::dispatch(d, f, Arc::new(HostTransport), &|k| crate::host::secret(k), &bo, op, &input)?;
        Ok(out.to_string())
    }
}

#[cfg(feature = "provisioning")]
pub mod provisioning {
    use pelty_provisioning::registrar::RegistrarModule;
    use pelty_provisioning::ProvisioningModule;

    #[cfg(target_family = "wasm")]
    fn backend(r: pelty_provisioning::http::RawRequest) -> Result<(u16, String), String> {
        crate::fetch(&r.method, &r.url, r.headers, r.body)
    }

    /// Route module HTTP to the host. Idempotent; called before every op.
    pub fn init() {
        #[cfg(target_family = "wasm")]
        pelty_provisioning::http::set_backend(backend);
    }

    fn bo(f: pelty_provisioning::wire::Fut<'_>) -> Result<serde_json::Value, String> {
        crate::block_on(f).map_err(|e| format!("transient:{e}"))?
    }

    pub fn describe(m: &dyn ProvisioningModule) -> String {
        pelty_provisioning::wire::describe(m)
    }
    pub fn call(m: &dyn ProvisioningModule, op: &str, input: &str) -> Result<String, String> {
        init();
        pelty_provisioning::wire::call(m, crate::host::secret("api_key"), &bo, op, input)
    }
    pub fn describe_registrar(m: &dyn RegistrarModule, settings: serde_json::Value) -> String {
        pelty_provisioning::wire::describe_registrar(m, settings)
    }
    pub fn call_registrar(m: &dyn RegistrarModule, op: &str, input: &str) -> Result<String, String> {
        init();
        pelty_provisioning::wire::call_registrar(m, &|f| crate::block_on(f).map_err(|e| format!("remote:{e}"))?, op, input)
    }
}

/// Export a provisioning addon from an expression building the module.
#[cfg(feature = "provisioning")]
#[macro_export]
macro_rules! provisioning_addon {
    ($module:expr) => {
        struct PeltyAddon;
        impl $crate::Guest for PeltyAddon {
            fn describe() -> String {
                $crate::provisioning::describe(&$module)
            }
            fn call(op: String, input: String) -> Result<String, String> {
                $crate::provisioning::call(&$module, &op, &input)
            }
            fn on_event(_name: String, _payload: String) -> Result<(), String> {
                Ok(())
            }
        }
        $crate::__cron_export!(PeltyAddon, |job| Err(format!("unknown cron job {job}")));
        $crate::export!(PeltyAddon with_types_in $crate);
    };
}

/// Export a registrar addon from an expression building the module and a
/// JSON settings schema.
#[cfg(feature = "provisioning")]
#[macro_export]
macro_rules! registrar_addon {
    ($module:expr, $settings:expr) => {
        struct PeltyAddon;
        impl $crate::Guest for PeltyAddon {
            fn describe() -> String {
                $crate::provisioning::describe_registrar(&$module, $settings)
            }
            fn call(op: String, input: String) -> Result<String, String> {
                $crate::provisioning::call_registrar(&$module, &op, &input)
            }
            fn on_event(_name: String, _payload: String) -> Result<(), String> {
                Ok(())
            }
        }
        $crate::__cron_export!(PeltyAddon, |job| Err(format!("unknown cron job {job}")));
        $crate::export!(PeltyAddon with_types_in $crate);
    };
}

/// Export a gateway addon from a module's `descriptor()` / `factory()`.
#[cfg(feature = "gateway")]
#[macro_export]
macro_rules! gateway_addon {
    ($desc:path, $factory:path) => {
        struct PeltyAddon;
        impl $crate::Guest for PeltyAddon {
            fn describe() -> String {
                $crate::gateway::describe(&$desc())
            }
            fn call(op: String, input: String) -> Result<String, String> {
                $crate::gateway::call(&$desc(), $factory, &op, &input)
            }
            fn on_event(_name: String, _payload: String) -> Result<(), String> {
                Ok(())
            }
        }
        $crate::__cron_export!(PeltyAddon, |job| Err(format!("unknown cron job {job}")));
        $crate::export!(PeltyAddon with_types_in $crate);
    };
}

